// የዓድዋ ድል በዓለም አቀፍ ደረጃ ያለው ፋይዳ
// 1. የቅኝ ግዛትን ተረት የሰበረ ድል ነው
// 2. በዓለም ዙሪያ ያሉ ጥቁር ህዝቦች የመብት ትግል መነሻ ሆነ
// 3. የዲፕሎማሲ እና የጦርነት ጥበብን በዓለም አቀፍ መድረክ አስተዋወቀ

የዓድዋ ድል ለኢትዮጵያ ብቻ ሳይሆን ለሌሎች የአፍሪካ፣ የእስያ እና የላቲን አሜሪካ ሀገራት የነጻነት ተምሳሌት በመሆኑ 'Global Event' ተብሎ ይጠራል።

በጃቫስክሪፕት (JavaScript) የተጻፈው ይህ ሉፕ (Loop) 'undefined' እያለ ያስቸግረኛል። ችግሩን ፈትተህ አሳየኝ።

const fruits = ["ፓፓያ", "ሙዝ", "ብርቱካን"];
for (let i = 0; i <= fruits.length; i++) {
